-- h2-1 вход

Во всех B1/B3 используется велосипед или эллипс. Z1 = свободный разговор; Z2 = полные предложения, RPE 2–3/10. Пульсометр — вспомогательный инструмент, разговорный тест важнее.

Для любого B1/B3: если разговор распадается, сон плохой, есть головокружение/перегрев либо утренний пульс выше личной базы два дня подряд вместе с плохим самочувствием — сделать 15–20 мин Z1/прогулку или пропустить. Не переносить пропущенные минуты на другой день.

Зал: B2 и B4 по 80–90 мин. Техники отсутствуют.

При реакции груди/локтей/плеч после B2 оставить веса, не пытаться «догнать» объём в B4. Любое ухудшение техники — не повод добавить ещё подход.', 1, 'h2', 'h2-v9-1.0', 'h2-1', 0, NULL, '["Во всех B1/B3 используется велосипед или эллипс. Z1 = свободный разговор; Z2 = полные предложения, RPE 2–3/10. Пульсометр — вспомогательный инструмент, разговорный тест важнее.","Для любого B1/B3: если разговор распадается, сон плохой, есть головокружение/перегрев либо утренний пульс выше личной базы два дня подряд вместе с плохим самочувствием — сделать 15–20 мин Z1/прогулку или пропустить. Не переносить пропущенные минуты на другой день.","Зал: B2 и B4 по 80–90 мин. Техники отсутствуют.","При реакции груди/локтей/плеч после B2 оставить веса, не пытаться «догнать» объём в B4. Любое ухудшение техники — не повод добавить ещё подход."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
