-- h2-6 интенсификация I + один низкорисковый грудной сет

Зал: B2 и B4 по 80–90 мин. Нет JM/узкого жима, AMRAP и техник.

Ключевая авторегуляция: дополнительный 4-й сет сведений — это весь прирост объёма. При жёлтой готовности, боли в плече/локте, RPE >8 на паузном жиме или ухудшении техники выполнить только базовые 3 сета сведений. Не добавлять другой грудной/трицепсовый жим.', 6, 'h2', 'h2-v9-1.0', 'h2-6', 40, NULL, '["Зал: B2 и B4 по 80–90 мин. Нет JM/узкого жима, AMRAP и техник.","Ключевая авторегуляция: дополнительный 4-й сет сведений — это весь прирост объёма. При жёлтой готовности, боли в плече/локте, RPE >8 на паузном жиме или ухудшении техники выполнить только базовые 3 сета сведений. Не добавлять другой грудной/трицепсовый жим."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
4-й сет — единственное добавление груди Ц6, лёгкое и контролируемое', 90, 'h2-6-b2-cable_fly_extra_h2_6', 'chest_accessory', NULL, NULL, NULL, NULL, NULL, NULL, true, 'Дополнительный 4-й сет сведений — это весь прирост объёма. При жёлтой готовности, боли в плече/локте, RPE >8 на паузном жиме или ухудшении техники выполнить только базовые 3 сета сведений. Не добавлять другой грудной/трицепсовый жим.', false, '{"key":"cable_fly_extra_h2_6","name":"Сведение на блоке","sets":"1","reps":"10–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"chest_accessory","optional":true,"condition":"Дополнительный 4-й сет сведений — это весь прирост объёма. При жёлтой готовности, боли в плече/локте, RPE >8 на паузном жиме или ухудшении техники выполнить только базовые 3 сета сведений. Не добавлять другой грудной/трицепсовый жим.","excludeFromTonnage":false,"notes":["4-й сет — единственное добавление груди Ц6, лёгкое и контролируемое"],"id":"h2-6-b2-cable_fly_extra_h2_6"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
прямой трицепс в B4 не нужен', 150, 'h2-6-b4-face_pull_external_rotation', 'rehab', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, true, '{"key":"face_pull_external_rotation","name":"Face pull + внешняя ротация","sets":"2 / 2","reps":"15 / 12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"role":"rehab","optional":false,"condition":null,"excludeFromTonnage":true,"notes":["легко","прямой трицепс в B4 не нужен"],"id":"h2-6-b4-face_pull_external_rotation"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;

-- h2-7 интенсификация II + условное сохранение добавочного сета

Зал: B2 и B4 по 80–90 мин. Нет техник и отказа.

В Ц7 разрешён четвёртый сет сведений только если все условия выполнены:

1. В Ц6 дополнительный четвёртый сет сведений был фактически выполнен при зелёной готовности; если его убрали по светофору, в Ц7 его не вводить.

2. В Ц6 не было зрительных/неврологических/кардиальных красных флагов, боли >2/10 или изменения траектории жима.

3. Все основные жимовые сеты Ц6 завершены без технической остановки, а последний сет паузного жима был не выше RPE 8.

4. В течение 24–48 ч после B2 и B4 Ц6 не было стойкого ухудшения сна, готовности или утреннего пульса два дня подряд.

5. В Ц7 перед B2 — зелёная готовность.

Если хотя бы одно условие не выполнено, Ц7 содержит только исходные 3 сета сведений. Нет переноса или компенсации этого сета в B4.

Ключевая авторегуляция: если 85 кг на разминке/первом сете уже требуют RPE выше плана, использовать 82,5 кг. При жёлтой готовности убрать условный четвёртый сет сведений и один аксессуарный сет; при оранжевой — действовать по общему светофору.', 7, 'h2', 'h2-v9-1.0', 'h2-7', 48, NULL, '["Зал: B2 и B4 по 80–90 мин. Нет техник и отказа.","В Ц7 разрешён четвёртый сет сведений только если все условия выполнены:","1. В Ц6 дополнительный четвёртый сет сведений был фактически выполнен при зелёной готовности; если его убрали по светофору, в Ц7 его не вводить.","2. В Ц6 не было зрительных/неврологических/кардиальных красных флагов, боли >2/10 или изменения траектории жима.","3. Все основные жимовые сеты Ц6 завершены без технической остановки, а последний сет паузного жима был не выше RPE 8.","4. В течение 24–48 ч после B2 и B4 Ц6 не было стойкого ухудшения сна, готовности или утреннего пульса два дня подряд.","5. В Ц7 перед B2 — зелёная готовность.","Если хотя бы одно условие не выполнено, Ц7 содержит только исходные 3 сета сведений. Нет переноса или компенсации этого сета в B4.","Ключевая авторегуляция: если 85 кг на разминке/первом сете уже требуют RPE выше плана, использовать 82,5 кг. При жёлтой готовности убрать условный четвёртый сет сведений и один аксессуарный сет; при оранжевой — действовать по общему светофору."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
последний RPE ≤8', 240, 'h2-7-b2-paused_bench_press', 'primary_press', 72.5, 75, 82.5, 85, NULL, 8, false, '85 кг только при соответствии цели', false, '{"key":"paused_bench_press","name":"Жим лёжа с паузой","sets":"4","reps":"6–8","percent":{"min":72.5,"max":75},"exampleKg":{"min":82.5,"max":85},"targetRpe":{"min":null,"max":8},"targetRir":null,"role":"primary_press","optional":false,"condition":"85 кг только при соответствии цели","excludeFromTonnage":false,"notes":["последний RPE ≤8"],"id":"h2-7-b2-paused_bench_press"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
4-й сет только по условиям выше', 90, 'h2-7-b2-cable_fly_extra_h2_7', 'chest_accessory', NULL, NULL, NULL, NULL, NULL, NULL, true, 'В Ц7 разрешён четвёртый сет сведений только если все условия выполнены: 1. В Ц6 дополнительный четвёртый сет сведений был фактически выполнен при зелёной готовности; если его убрали по светофору, в Ц7 его не вводить. 2. В Ц6 не было зрительных/неврологических/кардиальных красных флагов, боли >2/10 или изменения траектории жима. 3. Все основные жимовые сеты Ц6 завершены без технической остановки, а последний сет паузного жима был не выше RPE 8. 4. В течение 24–48 ч после B2 и B4 Ц6 не было стойкого ухудшения сна, готовности или утреннего пульса два дня подряд. 5. В Ц7 перед B2 — зелёная готовность. Если хотя бы одно условие не выполнено, Ц7 содержит только исходные 3 сета сведений. Нет переноса или компенсации этого сета в B4.', false, '{"key":"cable_fly_extra_h2_7","name":"Сведение на блоке","sets":"1","reps":"10–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"chest_accessory","optional":true,"condition":"В Ц7 разрешён четвёртый сет сведений только если все условия выполнены: 1. В Ц6 дополнительный четвёртый сет сведений был фактически выполнен при зелёной готовности; если его убрали по светофору, в Ц7 его не вводить. 2. В Ц6 не было зрительных/неврологических/кардиальных красных флагов, боли >2/10 или изменения траектории жима. 3. Все основные жимовые сеты Ц6 завершены без технической остановки, а последний сет паузного жима был не выше RPE 8. 4. В течение 24–48 ч после B2 и B4 Ц6 не было стойкого ухудшения сна, готовности или утреннего пульса два дня подряд. 5. В Ц7 перед B2 — зелёная готовность. Если хотя бы одно условие не выполнено, Ц7 содержит только исходные 3 сета сведений. Нет переноса или компенсации этого сета в B4.","excludeFromTonnage":false,"notes":["4-й сет только по условиям выше"],"id":"h2-7-b2-cable_fly_extra_h2_7"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;

-- h2-8 пик гипертрофийного блока, без эскалации усталости

Зал: B2 80–90 мин, B4 70–85 мин. Нет техник, отказа, JM и узкого жима.

База Ц8 — 2 сета сведений. Разрешён максимум один дополнительный лёгкий сет: сведение на блоке 1×12–15, RIR 4. Его можно выполнить только после базового B2 и только если:

до B2 была зелёная готовность;

все 4 сета паузного жима завершены при RPE ≤8 и с одинаковой техникой;

нет боли/симптомов и нет ухудшения восстановления после Ц7.

При любом сомнении дополнительного сета нет. Нельзя заменить его добавочным наклонным жимом, жимом сидя, трицепсом или иной техникой.

Ключевая авторегуляция: никакого автоматического повышения до 90 кг и никакого объёмного «пика» при жёлтой готовности. На жёлтом — 85–87,5 кг по RPE, без дополнительного грудного сета; на оранжевом — только техническая версия дня.', 8, 'h2', 'h2-v9-1.0', 'h2-8', 56, NULL, '["Зал: B2 80–90 мин, B4 70–85 мин. Нет техник, отказа, JM и узкого жима.","База Ц8 — 2 сета сведений. Разрешён максимум один дополнительный лёгкий сет: сведение на блоке 1×12–15, RIR 4. Его можно выполнить только после базового B2 и только если:","до B2 была зелёная готовность;","все 4 сета паузного жима завершены при RPE ≤8 и с одинаковой техникой;","нет боли/симптомов и нет ухудшения восстановления после Ц7.","При любом сомнении дополнительного сета нет. Нельзя заменить его добавочным наклонным жимом, жимом сидя, трицепсом или иной техникой.","Ключевая авторегуляция: никакого автоматического повышения до 90 кг и никакого объёмного «пика» при жёлтой готовности. На жёлтом — 85–87,5 кг по RPE, без дополнительного грудного сета; на оранжевом — только техническая версия дня."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
последний RPE ≤8', 240, 'h2-8-b2-paused_bench_press', 'primary_press', 75, 77.5, 85, 90, NULL, 8, false, 'если 90 кг выше цели — 87,5 кг', false, '{"key":"paused_bench_press","name":"Жим лёжа с паузой","sets":"4","reps":"5–6","percent":{"min":75,"max":77.5},"exampleKg":{"min":85,"max":90},"targetRpe":{"min":null,"max":8},"targetRir":null,"role":"primary_press","optional":false,"condition":"если 90 кг выше цели — 87,5 кг","excludeFromTonnage":false,"notes":["последний RPE ≤8"],"id":"h2-8-b2-paused_bench_press"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
+ максимум 1×12–15 RIR 4 только по правилу выше', 90, 'h2-8-b2-cable_fly_extra_h2_8', 'chest_accessory', NULL, NULL, NULL, NULL, NULL, NULL, true, 'Разрешён максимум один дополнительный лёгкий сет: сведение на блоке 1×12–15, RIR 4. Его можно выполнить только после базового B2 и только если: до B2 была зелёная готовность; все 4 сета паузного жима завершены при RPE ≤8 и с одинаковой техникой; нет боли/симптомов и нет ухудшения восстановления после Ц7. При любом сомнении дополнительного сета нет. Нельзя заменить его добавочным наклонным жимом, жимом сидя, трицепсом или иной техникой.', false, '{"key":"cable_fly_extra_h2_8","name":"Сведение на блоке","sets":"1","reps":"12–15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":4},"role":"chest_accessory","optional":true,"condition":"Разрешён максимум один дополнительный лёгкий сет: сведение на блоке 1×12–15, RIR 4. Его можно выполнить только после базового B2 и только если: до B2 была зелёная готовность; все 4 сета паузного жима завершены при RPE ≤8 и с одинаковой техникой; нет боли/симптомов и нет ухудшения восстановления после Ц7. При любом сомнении дополнительного сета нет. Нельзя заменить его добавочным наклонным жимом, жимом сидя, трицепсом или иной техникой.","excludeFromTonnage":false,"notes":["+ максимум 1×12–15 RIR 4 только по правилу выше"],"id":"h2-8-b2-cable_fly_extra_h2_8"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;

-- h2-9 мост к силовому блоку

Зал: B2 60–80 мин, B4 45–60 мин. Нет техник, отказа, тяжёлого узкого жима и тяжёлого трицепса.

После полной разминки выполнить одну свежую калибровочную тройку в соревновательном паузном жиме. Вес выбрать по разминке. Это не AMRAP, не настоящий 3ПМ и не итоговый e1RM-тест: остановить подход при RPE 7–8; использовать одну паузу, одну точку касания и видео сбоку.

Тройка может быть только одним из двух сопоставимых подтверждений для изменения RMref; сама по себе она RMref не меняет.

Ключевая авторегуляция: калибровочная тройка не пересчитывается в «тест силы» и не повторяется. Если разминка тяжёлая — сделать тройку легче либо отменить её и выполнить только лёгкие бэкоффы. Калории перевести от профицита к поддержанию.

После B4 Ц9 начинается V9-1: проходят три полных дня P1, P2, затем V9-1 B1 по его карточке — 40 минут с центральными 30 минутами Z2. При жёлтой готовности этот B1 сокращается до 15–20 минут Z1 или прогулки. Первая V9-B2 проводится на 4-й календарный день после H2 B4. Если свежесть не вернулась, добавить 1–4 дня отдыха; не начинать силовую фазу уставшим ради календаря.', 9, 'h2', 'h2-v9-1.0', 'h2-9', 64, '{"id":"h2-9-checkpoint","description":"После полной разминки выполнить одну свежую калибровочную тройку в соревновательном паузном жиме. Вес выбрать по разминке. Это не AMRAP, не настоящий 3ПМ и не итоговый e1RM-тест: остановить подход при RPE 7–8; использовать одну паузу, одну точку касания и видео сбоку. Тройка может быть только одним из двух сопоставимых подтверждений для изменения RMref; сама по себе она RMref не меняет. Контроль после H2: рабочие веса в диапазоне 6–12 повторений выросли или сохранились при меньшем RPE; масса тела росла примерно в коридоре +0,1–0,25%/нед до Ц9; плечо/поясница не хуже; пауза и траектория стабильнее; Ц9 пройден без выгорания. При сомнении RMref остаётся 115 кг."}'::jsonb, '["Зал: B2 60–80 мин, B4 45–60 мин. Нет техник, отказа, тяжёлого узкого жима и тяжёлого трицепса.","После полной разминки выполнить одну свежую калибровочную тройку в соревновательном паузном жиме. Вес выбрать по разминке. Это не AMRAP, не настоящий 3ПМ и не итоговый e1RM-тест: остановить подход при RPE 7–8; использовать одну паузу, одну точку касания и видео сбоку.","Тройка может быть только одним из двух сопоставимых подтверждений для изменения RMref; сама по себе она RMref не меняет.","Ключевая авторегуляция: калибровочная тройка не пересчитывается в «тест силы» и не повторяется. Если разминка тяжёлая — сделать тройку легче либо отменить её и выполнить только лёгкие бэкоффы. Калории перевести от профицита к поддержанию.","После B4 Ц9 начинается V9-1: проходят три полных дня P1, P2, затем V9-1 B1 по его карточке — 40 минут с центральными 30 минутами Z2. При жёлтой готовности этот B1 сокращается до 15–20 минут Z1 или прогулки. Первая V9-B2 проводится на 4-й календарный день после H2 B4. Если свежесть не вернулась, добавить 1–4 дня отдыха; не начинать силовую фазу уставшим ради календаря."]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
Вес выбрать по разминке. Это не AMRAP, не настоящий 3ПМ и не итоговый e1RM-тест: остановить подход при RPE 7–8; использовать одну паузу, одну точку касания и видео сбоку.
Тройка может быть только одним из двух сопоставимых подтверждений для изменения RMref; сама по себе она RMref не меняет.', 2, 'strength', NULL, NULL, 'h2-9-b2', 4, NULL, '{"slot":"B2","day":4,"kind":"strength","title":"B2 — зал A: калибровка и лёгкие бэкоффы","duration":{"min":60,"max":80},"cardio":null,"warmupLevel":null,"exercises":[{"key":"competition_paused_bench_calibration_triple","name":"Калибровочная тройка, соревновательный паузный жим","sets":"1","reps":"3","percent":null,"exampleKg":null,"targetRpe":{"min":7,"max":8},"targetRir":null,"role":"calibration","optional":false,"condition":"Если разминка тяжёлая — сделать тройку легче либо отменить её и выполнить только лёгкие бэкоффы.","excludeFromTonnage":false,"notes":["вес по разминке, RPE 7–8; при тяжёлой разминке снизить вес","Это не AMRAP, не настоящий 3ПМ и не итоговый e1RM-тест.","использовать одну паузу, одну точку касания и видео сбоку"],"id":"h2-9-b2-competition_paused_bench_calibration_triple"},{"key":"bench_press_light_backoffs","name":"Жим лёжа, облегчённые бэкоффы","sets":"2","reps":"4","percent":{"min":65,"max":70},"exampleKg":{"min":75,"max":80},"targetRpe":null,"targetRir":null,"role":"backoff","optional":false,"condition":null,"excludeFromTonnage":false,"notes":["качество и скорость, без гриндера"],"id":"h2-9-b2-bench_press_light_backoffs"},{"key":"spoto_press","name":"Spoto press","sets":"2","reps":"3","percent":{"min":60,"max":65},"exampleKg":{"min":70,"max":75},"targetRpe":null,"targetRir":null,"role":"technique_press","optional":false,"condition":null,"excludeFromTonnage":false,"notes":["стоп 1–2 см над грудью на 1–2 с, без расслабления"],"id":"h2-9-b2-spoto_press"},{"key":"chest_supported_t_bar_row","name":"Тяга Т-штанги с опорой грудью","sets":"3","reps":"8","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"role":"back_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-9-b2-chest_supported_t_bar_row"},{"key":"lat_pulldown","name":"Верхний блок","sets":"2","reps":"10","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"role":"back_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-9-b2-lat_pulldown"},{"key":"ez_bar_curl","name":"EZ-сгибание","sets":"2","reps":"10","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":3,"max":3},"role":"biceps_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-9-b2-ez_bar_curl"},{"key":"face_pull","name":"Face pull","sets":"2","reps":"15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"role":"rehab","optional":false,"condition":null,"excludeFromTonnage":true,"notes":["легко"],"id":"h2-9-b2-face_pull"}],"notes":["После полной разминки выполнить одну свежую калибровочную тройку в соревновательном паузном жиме.","Вес выбрать по разминке. Это не AMRAP, не настоящий 3ПМ и не итоговый e1RM-тест: остановить подход при RPE 7–8; использовать одну паузу, одну точку касания и видео сбоку.","Тройка может быть только одним из двух сопоставимых подтверждений для изменения RMref; сама по себе она RMref не меняет."],"id":"h2-9-b2","branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
