В V9-6, где условный сингл сам равен 92,5–95 кг, достаточно L2: не дублировать этот вес в разминке.', 2, 'strength', NULL, NULL, 'v9-6-b2', 4, 'L2', '{"slot":"B2","day":4,"kind":"strength","title":"Зал A","duration":{"min":60,"max":90},"cardio":null,"warmupLevel":"L2","exercises":[{"key":"competition_paused_bench_press_single","name":"соревновательный жим с паузой","sets":"1","reps":"1","percent":{"min":80,"max":82.5},"exampleKg":{"min":92.5,"max":95},"targetRpe":{"min":6,"max":7},"targetRir":null,"role":"conditional_single","optional":true,"condition":"Есть персональный медицинский допуск к тяжёлому натуживанию; врач не ограничил такую работу. На день тренировки — зелёная готовность, без красных флагов и офтальмологических симптомов. Есть страхующие или упоры, выставленные до подхода; одиночная тяжёлая работа в одиночку запрещена. Планируемый сингл ожидается на RPE 6–7; абсолютный потолок — RPE 8. Если допуска нет, готовность жёлтая/хуже, нет страховки/упоров, разминка тяжёлая или сингл требует RPE >8 — пропустить его без компенсации подходами, весом или упражнениями.","excludeFromTonnage":false,"notes":["условный технический сингл","максимум 8","выполнять только по единому правилу допуска"],"id":"v9-6-b2-competition_paused_bench_press_single"},{"key":"competition_paused_bench_press_backoff","name":"соревновательный жим с паузой","sets":"3","reps":"3","percent":{"min":77.5,"max":77.5},"exampleKg":{"min":90,"max":90},"targetRpe":{"min":7,"max":8},"targetRir":null,"role":"primary_backoff","optional":false,"condition":null,"excludeFromTonnage":false,"notes":["при превышении целевого RPE снизить до 87,5 кг","последний сет RPE 7–8"],"id":"v9-6-b2-competition_paused_bench_press_backoff"},{"key":"close_grip_bench_press","name":"узкий жим","sets":"2","reps":"5","percent":{"min":67.5,"max":67.5},"exampleKg":{"min":77.5,"max":77.5},"targetRpe":{"min":7,"max":7},"targetRir":null,"role":"secondary_press","optional":false,"condition":null,"excludeFromTonnage":false,"notes":["RPE около 7"],"id":"v9-6-b2-close_grip_bench_press"},{"key":"chest_supported_t_bar_row","name":"тяга Т-грифа с опорой","sets":"4","reps":"6–8","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"pull","optional":false,"condition":null,"excludeFromTonnage":true,"notes":[],"id":"v9-6-b2-chest_supported_t_bar_row"},{"key":"ez_curl","name":"EZ-сгибание","sets":"2","reps":"8–10","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"arms","optional":false,"condition":null,"excludeFromTonnage":true,"notes":[],"id":"v9-6-b2-ez_curl"},{"key":"face_pull","name":"face pull","sets":"2","reps":"15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"role":"rehab","optional":false,"condition":null,"excludeFromTonnage":true,"notes":["легко"],"id":"v9-6-b2-face_pull"}],"notes":["L2: L1 + 82,5×1–2, когда рабочая работа начинается примерно от 72,5% RMref.","В V9-6, где условный сингл сам равен 92,5–95 кг, достаточно L2: не дублировать этот вес в разминке."],"id":"v9-6-b2","branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
