{"conditionalTechnicalSinglesAllowed": true, "technicalSingleGates": ["Есть персональный медицинский допуск к тяжёлому натуживанию; врач не ограничил такую работу.", "На день тренировки зелёная готовность, без красных флагов и офтальмологических симптомов.", "Есть страхующие или упоры, выставленные до подхода; одиночная тяжёлая работа в одиночку запрещена.", "Планируемый сингл ожидается на RPE 6–7; абсолютный потолок RPE 8."], "items": ["При пропуске условного сингла не увеличивать число двойных подходов.", "Если 95 кг теряют паузу/траекторию или выходят за RPE 8, снизить до 92,5 кг и/или убрать последний сет.", "Проценты считаются от текущего RMref; килограммы — примеры для RMref 115 кг."]}', 18, 'v9', 'h2-v9-1.0', 'v9-9', 136, NULL, '["{\"conditionalTechnicalSinglesAllowed\": true, \"technicalSingleGates\": [\"Есть персональный медицинский допуск к тяжёлому натуживанию; врач не ограничил такую работу.\", \"На день тренировки зелёная готовность, без красных флагов и офтальмологических симптомов.\", \"Есть страхующие или упоры, выставленные до подхода; одиночная тяжёлая работа в одиночку запрещена.\", \"Планируемый сингл ожидается на RPE 6–7; абсолютный потолок RPE 8.\"], \"items\": [\"При пропуске условного сингла не увеличивать число двойных подходов.\", \"Если 95 кг теряют паузу/траекторию или выходят за RPE 8, снизить до 92,5 кг и/или убрать последний сет.\", \"Проценты считаются от текущего RMref; килограммы — примеры для RMref 115 кг.\"]}"]'::jsonb) ON CONFLICT (program_version, program_key) WHERE program_key IS NOT NULL DO UPDATE SET number=EXCLUDED.number, name=EXCLUDED.name, macrocycle=EXCLUDED.macrocycle, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, block=EXCLUDED.block, day_offset=EXCLUDED.day_offset, checkpoint=EXCLUDED.checkpoint, rules=EXCLUDED.rules;
