INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-1.0' AND program_key='h2-7'), 'B2', 'B2 — зал A', '', 2, 'strength', NULL, NULL, 'h2-7-b2', 4, NULL, '{"slot":"B2","day":4,"kind":"strength","title":"B2 — зал A","duration":{"min":80,"max":90},"cardio":null,"warmupLevel":null,"exercises":[{"key":"paused_bench_press","name":"Жим лёжа с паузой","sets":"4","reps":"6–8","percent":{"min":72.5,"max":75},"exampleKg":{"min":82.5,"max":85},"targetRpe":{"min":null,"max":8},"targetRir":null,"role":"primary_press","optional":false,"condition":"85 кг только при соответствии цели","excludeFromTonnage":false,"notes":["последний RPE ≤8"],"id":"h2-7-b2-paused_bench_press"},{"key":"cable_fly_base","name":"Сведение на блоке","sets":"3","reps":"10–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"chest_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-cable_fly_base"},{"key":"cable_fly_extra_h2_7","name":"Сведение на блоке","sets":"1","reps":"10–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"chest_accessory","optional":true,"condition":"В Ц7 разрешён четвёртый сет сведений только если все условия выполнены: 1. В Ц6 дополнительный четвёртый сет сведений был фактически выполнен при зелёной готовности; если его убрали по светофору, в Ц7 его не вводить. 2. В Ц6 не было зрительных/неврологических/кардиальных красных флагов, боли >2/10 или изменения траектории жима. 3. Все основные жимовые сеты Ц6 завершены без технической остановки, а последний сет паузного жима был не выше RPE 8. 4. В течение 24–48 ч после B2 и B4 Ц6 не было стойкого ухудшения сна, готовности или утреннего пульса два дня подряд. 5. В Ц7 перед B2 — зелёная готовность. Если хотя бы одно условие не выполнено, Ц7 содержит только исходные 3 сета сведений. Нет переноса или компенсации этого сета в B4.","excludeFromTonnage":false,"notes":["4-й сет только по условиям выше"],"id":"h2-7-b2-cable_fly_extra_h2_7"},{"key":"chest_supported_t_bar_row","name":"Тяга Т-штанги с опорой грудью","sets":"4","reps":"8","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":3},"role":"back_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-chest_supported_t_bar_row"},{"key":"lat_pulldown","name":"Верхний блок","sets":"2","reps":"8–10","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":3},"role":"back_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-lat_pulldown"},{"key":"overhead_cable_triceps_extension","name":"Трицепс из-за головы на блоке","sets":"3","reps":"10–15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"triceps_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-overhead_cable_triceps_extension"},{"key":"ez_bar_curl","name":"EZ-сгибание","sets":"2–3","reps":"8–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":1,"max":2},"role":"biceps_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-ez_bar_curl"},{"key":"lateral_raise","name":"Махи в стороны","sets":"3","reps":"12–15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"deltoid_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-lateral_raise"},{"key":"face_pull","name":"Face pull","sets":"2","reps":"15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"role":"rehab","optional":false,"condition":null,"excludeFromTonnage":true,"notes":["легко"],"id":"h2-7-b2-face_pull"}],"notes":[],"id":"h2-7-b2","branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
