INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='h2-7-b2'), 2, 'Сведение на блоке', '2 RIR', NULL, '10–12', '3', 2, 2, '', 90, 'h2-7-b2-cable_fly_base', 'chest_accessory', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, false, '{"key":"cable_fly_base","name":"Сведение на блоке","sets":"3","reps":"10–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"chest_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-7-b2-cable_fly_base"}'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET workout_id=EXCLUDED.workout_id, sort_order=EXCLUDED.sort_order, name=EXCLUDED.name, weight_text=EXCLUDED.weight_text, pct_of_tm=EXCLUDED.pct_of_tm, target_reps=EXCLUDED.target_reps, target_sets=EXCLUDED.target_sets, target_rir_min=EXCLUDED.target_rir_min, target_rir_max=EXCLUDED.target_rir_max, comment=EXCLUDED.comment, rest_seconds=EXCLUDED.rest_seconds, role=EXCLUDED.role, pct_min=EXCLUDED.pct_min, pct_max=EXCLUDED.pct_max, example_kg_min=EXCLUDED.example_kg_min, example_kg_max=EXCLUDED.example_kg_max, target_rpe_min=EXCLUDED.target_rpe_min, target_rpe_max=EXCLUDED.target_rpe_max, is_optional=EXCLUDED.is_optional, condition_code=EXCLUDED.condition_code, exclude_from_tonnage=EXCLUDED.exclude_from_tonnage, prescription=EXCLUDED.prescription;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='h2-7-b2'), 3, 'Сведение на блоке', '2 RIR', NULL, '10–12', '1', 2, 2, 'В Ц7 разрешён четвёртый сет сведений только если все условия выполнены: 1. В Ц6 дополнительный четвёртый сет сведений был фактически выполнен при зелёной готовности; если его убрали по светофору, в Ц7 его не вводить. 2. В Ц6 не было зрительных/неврологических/кардиальных красных флагов, боли >2/10 или изменения траектории жима. 3. Все основные жимовые сеты Ц6 завершены без технической остановки, а последний сет паузного жима был не выше RPE 8. 4. В течение 24–48 ч после B2 и B4 Ц6 не было стойкого ухудшения сна, готовности или утреннего пульса два дня подряд. 5. В Ц7 перед B2 — зелёная готовность. Если хотя бы одно условие не выполнено, Ц7 содержит только исходные 3 сета сведений. Нет переноса или компенсации этого сета в B4.
