INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-1.0' AND program_key='h2-8'), 'B2', 'B2 — зал A', '', 2, 'strength', NULL, NULL, 'h2-8-b2', 4, NULL, '{"slot":"B2","day":4,"kind":"strength","title":"B2 — зал A","duration":{"min":80,"max":90},"cardio":null,"warmupLevel":null,"exercises":[{"key":"paused_bench_press","name":"Жим лёжа с паузой","sets":"4","reps":"5–6","percent":{"min":75,"max":77.5},"exampleKg":{"min":85,"max":90},"targetRpe":{"min":null,"max":8},"targetRir":null,"role":"primary_press","optional":false,"condition":"если 90 кг выше цели — 87,5 кг","excludeFromTonnage":false,"notes":["последний RPE ≤8"],"id":"h2-8-b2-paused_bench_press"},{"key":"cable_fly_base","name":"Сведение на блоке","sets":"2","reps":"10–12","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"chest_accessory","optional":false,"condition":null,"excludeFromTonnage":false,"notes":[],"id":"h2-8-b2-cable_fly_base"},{"key":"cable_fly_extra_h2_8","name":"Сведение на блоке","sets":"1","reps":"12–15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":4,"max":4},"role":"chest_accessory","optional":true,"condition":"Разрешён максимум один дополнительный лёгкий сет: сведение на блоке 1×12–15, RIR 4. Его можно выполнить только после базового B2 и только если: до B2 была зелёная готовность; все 4 сета паузного жима завершены при RPE ≤8 и с одинаковой техникой; нет боли/симптомов и нет ухудшения восстановления после Ц7. При любом сомнении дополнительного сета нет. Нельзя заменить его добавочным наклонным жимом, жимом сидя, трицепсом или иной техникой.","excludeFromTonnage":false,"notes":["+ максимум 1×12–15 RIR 4 только по правилу выше"],"id":"h2-8-b2-cable_fly_extra_h2_8"},{"key":"chest_supported_t_bar_row","name":"Тяга Т-штанги с опорой грудью","sets":"4","reps":"8","perce