INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v9-6-b2'), 1, 'соревновательный жим с паузой', '80–82.5% RMref · при RMref 115: 92.5–95 кг', NULL, '1', '1', NULL, NULL, 'Есть персональный медицинский допуск к тяжёлому натуживанию; врач не ограничил такую работу. На день тренировки — зелёная готовность, без красных флагов и офтальмологических симптомов. Есть страхующие или упоры, выставленные до подхода; одиночная тяжёлая работа в одиночку запрещена. Планируемый сингл ожидается на RPE 6–7; абсолютный потолок — RPE 8. Если допуска нет, готовность жёлтая/хуже, нет страховки/упоров, разминка тяжёлая или сингл требует RPE >8 — пропустить его без компенсации подходами, весом или упражнениями.
