INSERT INTO workouts (cycle_id, label, title, notes, sort_order, kind, cardio_zone, cardio_minutes, program_key, day_in_cycle, warmup_level, prescription, branches) VALUES ((SELECT id FROM cycles WHERE program_version='h2-v9-1.0' AND program_key='v9-7'), 'B2', 'Зал A', 'L3: L2 + 92,5×1 перед условным синглом от ~85% RMref.', 2, 'strength', NULL, NULL, 'v9-7-b2', 4, 'L3', '{"slot":"B2","day":4,"kind":"strength","title":"Зал A","duration":{"min":60,"max":90},"cardio":null,"warmupLevel":"L3","exercises":[{"key":"competition_paused_bench_press_single","name":"соревновательный жим с паузой","sets":"1","reps":"1","percent":{"min":85,"max":85},"exampleKg":{"min":97.5,"max":97.5},"targetRpe":{"min":6,"max":7},"targetRir":null,"role":"conditional_single","optional":true,"condition":"Есть персональный медицинский допуск к тяжёлому натуживанию; врач не ограничил такую работу. На день тренировки — зелёная готовность, без красных флагов и офтальмологических симптомов. Есть страхующие или упоры, выставленные до подхода; одиночная тяжёлая работа в одиночку запрещена. Планируемый сингл ожидается на RPE 6–7; абсолютный потолок — RPE 8. Если допуска нет, готовность жёлтая/хуже, нет страховки/упоров, разминка тяжёлая или сингл требует RPE >8 — пропустить его без компенсации подходами, весом или упражнениями.","excludeFromTonnage":false,"notes":["условный технический сингл","≈85%","максимум 8"],"id":"v9-7-b2-competition_paused_bench_press_single"},{"key":"competition_paused_bench_press_backoff","name":"соревновательный жим с паузой","sets":"3","reps":"3","percent":{"min":80,"max":80},"exampleKg":{"min":92.5,"max":92.5},"targetRpe":{"min":null,"max":8},"targetRir":null,"role":"primary_backoff","optional":false,"condition":null,"excludeFromTonnage":false,"notes":["последний сет RPE ≤8"],"id":"v9-7-b2-competition_paused_bench_press_backoff"},{"key":"close_grip_bench_press","name":"узкий жим","sets":"2","reps":"4–5","percent":{"min":70,"max":70},"exampleKg":{"min":80,"max":80},"targetRpe":{"min":7,"max":8},"targetRir":null,"role":"secondary_press","optional":false,"condition":null,"excludeFromTonnage":false,"notes":["Узкий жим не делать через боль в локтях; при проблеме он отменяется без замены тяжёлым вариантом."],"id":"v9-7-b2-close_grip_bench_press"},{"key":"chest_supported_t_bar_row","name":"тяга Т-грифа с опорой","sets":"4","reps":"6–8","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"pull","optional":false,"condition":null,"excludeFromTonnage":true,"notes":[],"id":"v9-7-b2-chest_supported_t_bar_row"},{"key":"ez_curl","name":"EZ-сгибание","sets":"2","reps":"8–10","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":{"min":2,"max":2},"role":"arms","optional":false,"condition":null,"excludeFromTonnage":true,"notes":[],"id":"v9-7-b2-ez_curl"},{"key":"face_pull","name":"face pull","sets":"2","reps":"15","percent":null,"exampleKg":null,"targetRpe":null,"targetRir":null,"role":"rehab","optional":false,"condition":null,"excludeFromTonnage":true,"notes":["легко"],"id":"v9-7-b2-face_pull"}],"notes":["L3: L2 + 92,5×1 перед условным синглом от ~85% RMref."],"id":"v9-7-b2","branches":[]}'::jsonb, '[]'::jsonb) ON CONFLICT (program_key) WHERE program_key IS NOT NULL DO UPDATE SET cycle_id=EXCLUDED.cycle_id, label=EXCLUDED.label, title=EXCLUDED.title, notes=EXCLUDED.notes, sort_order=EXCLUDED.sort_order, kind=EXCLUDED.kind, cardio_zone=EXCLUDED.cardio_zone, cardio_minutes=EXCLUDED.cardio_minutes, day_in_cycle=EXCLUDED.day_in_cycle, warmup_level=EXCLUDED.warmup_level, prescription=EXCLUDED.prescription, branches=EXCLUDED.branches;
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v9-7-b2'), 1, 'соревновательный жим с паузой', '85% RMref · при RMref 115: 97.5 кг', 85, '1', '1', NULL, NULL, 'Есть персональный медицинский допуск к тяжёлому натуживанию; врач не ограничил такую работу. На день тренировки — зелёная готовность, без красных флагов и офтальмологических симптомов. Есть страхующие или упоры, выставленные до подхода; одиночная тяжёлая работа в одиночку запрещена. Планируемый сингл ожидается на RPE 6–7; абсолютный потолок — RPE 8. Если допуска нет, готовность жёлтая/хуже, нет страховки/упоров, разминка тяжёлая или сингл требует RPE >8 — пропустить его без компенсации подходами, весом или упражнениями.
