INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v9-13-b2'), 1, 'соревновательный паузный жим', '8–8.5 RPE', NULL, '3', '1', NULL, NULL, 'Зелёная готовность. | Обязательны страхующие или упоры. | Записать видео сбоку.
INSERT INTO workout_exercises (workout_id, sort_order, name, weight_text, pct_of_tm, target_reps, target_sets, target_rir_min, target_rir_max, comment, rest_seconds, program_key, role, pct_min, pct_max, example_kg_min, example_kg_max, target_rpe_min, target_rpe_max, is_optional, condition_code, exclude_from_tonnage, prescription) VALUES ((SELECT id FROM workouts WHERE program_key='v9-13-b2'), 2, 'прямой 1ПМ', NULL, NULL, '1', 'не более 3', NULL, NULL, 'Есть явное персональное разрешение врача именно на планируемый уровень сопротивления и натуживания; при высокой миопии или иных офтальмологических факторах риска проведена актуальная оценка офтальмолога/ретинолога и получены персональные ограничения. | Зелёная готовность; нет офтальмологических, неврологических, сердечных, ортостатических или лекарственно значимых симптомов и нет боли, меняющей технику. | Нет недавнего изменения лекарственной схемы, болезни, обезвоживания или выраженного недосыпа. | До начала разминки выставлены надёжные упоры или присутствуют компетентные страхующие; одиночный тест в одиночку запрещён. | V9-11 условный сингл прошёл уверенно в пределах RPE ≤8, а V9-12 B2 и праймер прошли без ухудшения техники или симптомов. | Выбран именно прямой 1ПМ, а не последовательность «тройка + 1ПМ» в один день.
